'use strict';
const KEY='nexo-iptv-v1';
const sharedCatalog=document.querySelector('meta[name="nexo-catalog"]')?.content==='server';
const catalogClient=sharedCatalog?new NexoCatalog.Client():null;
let db={clients:[],channels:[],packages:[]},storageOK=true,catalogReady=!sharedCatalog,catalogSaving=false,catalogLoading=false,catalogError='';
if(!sharedCatalog)try{const raw=localStorage.getItem(KEY);if(raw)db=validate(JSON.parse(raw));}catch{storageOK=false;}

const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const id=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};const active=c=>c.enabled&&c.expires>=today();let page='recursos',search='';
function validate(x){if(!x||!['clients','channels','packages'].every(k=>Array.isArray(x[k])&&x[k].length<=10000))throw Error('Formato de respaldo inválido');for(const k of ['clients','channels','packages']){const ids=new Set();for(const r of x[k]){if(!r||typeof r.id!=='string'||typeof r.name!=='string'||r.name.length>200||ids.has(r.id))throw Error('Registros inválidos');ids.add(r.id);if(k==='channels'&&(!validURL(r.url)||typeof r.group!=='string'||typeof r.enabled!=='boolean'))throw Error('Canal inválido');if(k==='packages'&&(!Array.isArray(r.channels)||!r.channels.every(v=>typeof v==='string')))throw Error('Paquete inválido');if(k==='clients'&&(typeof r.packageId!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(r.expires)||!Number.isInteger(r.connections)||r.connections<1||r.connections>100||typeof r.enabled!=='boolean'))throw Error('Cliente inválido');}}if(x.packages.some(p=>p.channels.some(c=>!x.channels.some(ch=>ch.id===c)))||x.clients.some(c=>!x.packages.some(p=>p.id===c.packageId)))throw Error('Referencias incompletas');return {clients:x.clients,channels:x.channels,packages:x.packages};}
function validURL(s){if(typeof s!=='string'||/[\x00-\x20]/.test(s)||s.length>4096)return false;try{const u=new URL(s);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password;}catch{return false;}}
async function persist(next){
 if(catalogSaving||!catalogReady){toast('Actualiza el catálogo antes de guardar.');return false;}
 try{next=validate(next);}catch(error){toast(error.message);return false;}
 if(!sharedCatalog){try{localStorage.setItem(KEY,JSON.stringify(next));db=next;storageOK=true;return true;}catch{toast('No se pudo guardar. Exporta un respaldo y revisa el almacenamiento.');return false;}}
 catalogSaving=true;catalogStatus();
 try{db=validate(await catalogClient.save(next));return true;}
 catch(error){catalogError=error.message;catalogReady=false;render();toast(error.message);return false;}
 finally{catalogSaving=false;catalogStatus();}
}
function catalogStatus(){
 const box=$('#catalog-status');if(!box)return;
 const mode=sharedCatalog?'Catálogo compartido en el servidor':'Catálogo en este navegador';
 const detail=sharedCatalog?(catalogError||(!catalogReady?'Conectando con el catálogo…':catalogSaving?'Guardando cambios…':'Datos guardados en el servidor · revisión '+catalogClient.revision)):'Los datos locales no se comparten entre equipos. Exporta un respaldo para conservarlos.';
 box.className='catalog-status'+(catalogError?' error':'');
 box.innerHTML='<div><strong>'+esc(mode)+'</strong><p role="status">'+esc(detail)+'</p></div>'+(sharedCatalog?'<div class="catalog-actions"><button class="small" data-catalog-refresh '+(catalogSaving||catalogLoading?'disabled':'')+'>Actualizar</button>'+(catalogReady?'<button class="small" data-catalog-local '+(catalogSaving?'disabled':'')+'>Importar copia local</button>':'')+'</div>':'');
 const search=$('#global-search');if(search)search.disabled=!catalogReady;
 const save=$('#form button[type="submit"]');if(save)save.disabled=catalogSaving||!catalogReady;
 const primary=$('#primary');if(primary)primary.disabled=Boolean(mapping[page])&&(catalogSaving||!catalogReady);
 const label=$('#catalog-mode-label');if(label)label.textContent=sharedCatalog?'Gestión central · Monitorización mediante agente':'Gestión local · Monitorización mediante agente';
 const caption=$('#catalog-mode-caption');if(caption)caption.textContent=sharedCatalog?'El catálogo se guarda en el servidor. La telemetría requiere conectar tu agente Linux.':'Los registros se guardan en este navegador. Los recursos requieren conectar tu agente Linux.';
}
async function refreshCatalog(){
 if(!sharedCatalog||catalogSaving||catalogLoading)return;
 catalogLoading=true;catalogReady=false;catalogError='';render();
 try{db=validate(await catalogClient.load());catalogReady=true;}
 catch(error){catalogError=error.message;}
 finally{catalogLoading=false;}
 render();
}
async function importLocalCatalog(){
 if(!catalogReady||catalogSaving)return;
 try{const raw=localStorage.getItem(KEY);if(!raw){toast('No hay una copia local en este origen. Puedes restaurar un respaldo JSON.');return;}
 const next=validate(JSON.parse(raw));
 if(!confirm('Se reemplazará todo el catálogo del servidor por la copia de este navegador. Exporta antes un respaldo. ¿Continuar?'))return;
 if(await persist(next)){render();toast('Copia local guardada en el servidor.');}
 }catch(error){toast('No se pudo importar: '+error.message);}
}
function exportBackup(){if(!catalogReady){toast('Actualiza el catálogo antes de exportar.');return;}download('nexo-respaldo-'+today()+'.json',JSON.stringify(db,null,2),'application/json');}

function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4200);}
function download(name,content,type){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function badge(ok,yes='Activo',no='Inactivo'){return `<span class="badge ${ok?'':'muted'}">${ok?yes:no}</span>`;}
function empty(type){const info={clients:['Sin clientes todavía','Crea un paquete y asigna tu primer cliente.','Nuevo cliente'],channels:['Tu catálogo empieza aquí','Añade una fuente HTTP o HTTPS de contenido propio o autorizado.','Añadir canal'],packages:['Crea tu primera oferta','Agrupa tus canales en paquetes para asignarlos a tus clientes.','Crear paquete']};const [a,b,c]=info[type];return `<div class="empty"><div class="empty-symbol">▦</div><h3>${a}</h3><p>${b}</p><button class="primary" data-new="${type}">＋ ${c}</button></div>`;}
function actions(type,r){return `<div class="row-actions">${type==='clients'?`<button data-m3u="${esc(r.id)}" ${!active(r)?'disabled':''}>M3U</button>`:''}<button data-edit="${type}" data-id="${esc(r.id)}">Editar</button><button data-delete="${type}" data-id="${esc(r.id)}" aria-label="Eliminar ${esc(r.name)}">×</button></div>`;}
function table(type,rows){if(!catalogReady)return '<div class="catalog-unavailable">'+esc(catalogError||'Cargando catálogo del servidor…')+'</div>';if(!db[type].length)return empty(type);if(!rows.length)return '<div class="empty"><h3>No hay coincidencias</h3><p>Prueba con otro nombre.</p></div>';const heads={clients:['CLIENTE','PAQUETE','VENCIMIENTO','ESTADO','ACCIONES'],channels:['CANAL','CATEGORÍA','FUENTE','ESTADO','ACCIONES'],packages:['PAQUETE','CANALES','CLIENTES','ACCIONES']};return `<div class="table-wrap"><table><thead><tr>${heads[type].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>{let cols;if(type==='clients'){const p=db.packages.find(p=>p.id===r.packageId);cols=[`<strong>${esc(r.name)}</strong><small>${r.connections} conexiones configuradas</small>`,esc(p?.name||'Sin paquete'),esc(r.expires),badge(active(r), 'Activo',r.enabled?'Vencido':'Suspendido')];}else if(type==='channels'){cols=[`<strong>${esc(r.name)}</strong>`,esc(r.group),`<span title="${esc(r.url)}">${esc(new URL(r.url).hostname)}</span>`,badge(r.enabled,'Habilitado','Deshabilitado')];}else cols=[`<strong>${esc(r.name)}</strong>`,String(r.channels.length),String(db.clients.filter(c=>c.packageId===r.id).length)];return `<tr>${cols.map(c=>`<td>${c}</td>`).join('')}<td>${actions(type,r)}</td></tr>`;}).join('')}</tbody></table></div>`;}
const mapping={clientes:'clients',canales:'channels',paquetes:'packages'};const titles={servers:['Servers','Inventario y recursos del servidor','Servers'],proxies:['Manage Proxies','Definiciones de proxy','Manage Proxies'],'server-order':['Server Order','Orden de servidores','Server Order'],'process-monitor':['Process Monitor','Procesos del servidor','Process Monitor'],recursos:['Dashboard','Recursos, tráfico y salud de tu servidor en una sola vista.','Centro de operación'],conexiones:['Mapa de conexiones','Inspecciona conexiones TCP y sesiones reportadas por tu servicio IPTV.','Mapa de conexiones'],inicio:['Tu servicio, bajo control.','Organiza tu catálogo y prepara tu operación IPTV.','Vista general'],clientes:['Clientes','Administra suscripciones, vencimientos y paquetes.','Clientes'],canales:['Canales en vivo','Organiza las fuentes de tu catálogo.','Canales en vivo'],paquetes:['Paquetes','Diseña tu oferta y distribuye tus canales.','Paquetes'],proyecto:['De la gestión a la transmisión.','Alcance de esta versión y próximos módulos.','Estado del proyecto']};
function overview(){if(!catalogReady)return '<section class="panel catalog-unavailable">'+esc(catalogError||'Cargando catálogo…')+'</section>';return NexoMonitor.summary()+`<div class="stats">${[['Clientes activos',db.clients.filter(active).length,'De '+db.clients.length+' clientes registrados'],['Canales habilitados',db.channels.filter(c=>c.enabled).length,'Fuentes registradas · sin supervisión'],['Paquetes',db.packages.length,'Ofertas en tu catálogo'],['Por vencer',db.clients.filter(c=>active(c)&&c.expires<=new Date(Date.now()+7*864e5).toISOString().slice(0,10)).length,'En los próximos 7 días']].map(([a,b,c])=>`<div class="stat"><div class="stat-label">${a}<span>↗</span></div><div class="stat-value">${b}</div><small>${c}</small></div>`).join('')}</div><section class="panel"><div class="panel-top"><div><h2>Clientes recientes</h2><p>Las últimas suscripciones de tu operación</p></div><a class="link-button" href="#clientes">Ver todos →</a></div>${table('clients',db.clients.slice(-5).reverse())}</section><div class="grid-two"><section class="panel"><div class="panel-top"><div><h2>Prepara tu primera lista</h2><p>Tres pasos para organizar tu catálogo</p></div><span class="badge">Inicio rápido</span></div><div class="steps">${[['01','Añade tus canales','Registra fuentes HTTP o HTTPS y su categoría.','canales'],['02','Arma un paquete','Selecciona los canales que incluirá cada oferta.','paquetes'],['03','Crea un cliente y exporta','Asigna un paquete y descarga su lista M3U.','clientes']].map(([n,t,d,h])=>`<a class="step" href="#${h}"><span class="step-num">${n}</span><div><strong>${t} →</strong><p>${d}</p></div></a>`).join('')}</div></section><section class="panel storage"><div class="eyebrow">TU INFORMACIÓN</div><h3 style="margin-top:15px">${sharedCatalog?'Catálogo central, respaldo portátil.':'Control local, respaldo portátil.'}</h3><p>${sharedCatalog?'Los registros se guardan en el servidor y se comparten entre navegadores autorizados. Exporta un respaldo antes de una restauración.':'Los registros viven en este navegador. Descarga un respaldo antes de cambiar de equipo o borrar los datos del sitio.'}</p><div class="progress"><span></span></div><p>${sharedCatalog?'Usa Actualizar para cargar los últimos cambios. Se detectan conflictos al guardar.':'El modo local no sincroniza datos entre dispositivos.'}</p><button data-backup>↓ Exportar respaldo</button><button data-import>↑ Restaurar</button></section></div>`;}
function roadmap(){return `<div class="module-grid">${[['01','Gestión de catálogo','Disponible','Alta, edición y eliminación de clientes, paquetes y canales. Datos centrales en la instalación Debian; modo local y respaldo JSON.',true],['02','Exportación M3U','Disponible','Listas con los canales habilitados del paquete de un cliente vigente. Incluyen las URLs de origen.',true],['03','API de catálogo','Disponible en Debian','Catálogo central en SQLite, acceso de administrador por HTTPS y protección frente a cambios simultáneos. Roles y API para reproductores pendientes.',true],['04','Distribución de vídeo','Pendiente','Nodos de streaming, ingestión con FFmpeg, HLS, supervisión y recuperación de fuentes.',false],['05','Control de conexiones','Pendiente','Sesiones simultáneas, revocación y límites aplicados por el servidor. El campo actual solo registra el valor.',false],['07','Telemetría y mapas','Con agente','CPU, RAM, disco, red y sockets TCP cada 5 s. Topología y geografía con coordenadas de la integración. Requiere instalar el agente Linux.',true],['06','Expansión del servicio','Pendiente','EPG, películas y series, revendedores, facturación y pruebas de compatibilidad con reproductores.',false]].map(([n,t,s,d,a])=>`<section class="panel module"><div class="eyebrow">MÓDULO ${n}</div><h3>${t}</h3>${badge(a,s,s)}<p style="margin-top:15px">${d}</p></section>`).join('')}</div><section class="panel storage" style="margin-top:22px"><h3>Alcance de esta entrega</h3><p>Es una primera base de gestión. No reemplaza todavía a XUI One en producción. Las listas M3U contienen fuentes directas: no incluyen autenticación, caducidad ni límites aplicados al reproducir. No se han validado APIs de reproductores ni se está transmitiendo vídeo desde este sitio.</p><div class="backup-actions"><button data-backup>↓ Exportar respaldo JSON</button><button data-import>↑ Restaurar respaldo</button></div></section>`;}
function render(){page=location.hash.slice(1)||'recursos';if(!titles[page])page='inicio';document.body.dataset.page=page;NexoShell.sync();catalogStatus();const [h,s,c]=titles[page];$('#heading').textContent=h;$('#subtitle').textContent=s;$('#crumb').textContent=c;document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));const type=mapping[page]||'clients';$('#primary').textContent=({clients:'＋ Nuevo cliente',channels:'＋ Añadir canal',packages:'＋ Crear paquete'})[type];$('#primary').hidden=page==='proyecto';if(NexoServers.isPage(page)){$('#primary').hidden=false;$('#primary').textContent=page==='servers'?'Install Server':page==='proxies'?'Add Proxy':page==='process-monitor'?'Manage Servers':'Export inventory';$('#primary').classList.add('infra-primary');$('#primary').onclick=()=>{if(page==='servers')NexoServers.editor();if(page==='proxies')NexoServers.editor(null,true);if(page==='process-monitor')location.hash='servers';if(page==='server-order')download('nexo-infrastructure-'+today()+'.json',JSON.stringify(NexoServers.exportConfig(),null,2),'application/json');};NexoServers.render();return;}$('#primary').classList.remove('infra-primary');if(NexoMonitor.isPage(page)){$('#primary').hidden=false;$('#primary').textContent='＋ Conectar servidor';$('#primary').onclick=()=>NexoMonitor.settings();NexoMonitor.draw();return;}$('#primary').onclick=()=>edit(type);if(page==='inicio')$('#view').innerHTML=overview();else if(page==='proyecto')$('#view').innerHTML=roadmap();else{$('#view').innerHTML=`<section class="panel"><div class="panel-top"><div><h2>${c} <span class="badge">${catalogReady?db[type].length:'—'}</span></h2><p>${type==='clients'?'Los límites configurados se aplicarán al integrar el servidor.':(sharedCatalog?'Catálogo compartido en el servidor.':'Catálogo guardado en este navegador.')}</p></div><div class="toolbar"><input id="search" type="search" placeholder="Buscar por nombre…" aria-label="Buscar por nombre" value="${esc(search)}"></div></div><div id="results">${table(type,db[type].filter(r=>r.name.toLowerCase().includes(search.toLowerCase())))}</div></section>`;$('#search').oninput=e=>{search=e.target.value;$('#results').innerHTML=table(type,db[type].filter(r=>r.name.toLowerCase().includes(search.toLowerCase())));};}}
function edit(type,rid){if(!catalogReady||catalogSaving){toast('Actualiza el catálogo antes de editar.');return;}const formRevision=catalogClient?.revision;if(type==='clients'&&!db.packages.length){toast('Primero crea un paquete para asignarlo al cliente.');location.hash='paquetes';return;}const r=db[type].find(x=>x.id===rid)||{};$('#dialog-title').textContent=(rid?'Editar ':'Crear ')+({clients:'cliente',channels:'canal',packages:'paquete'})[type];let f=`<label for="name">Nombre</label><input id="name" name="name" required maxlength="120" value="${esc(r.name||'')}" autocomplete="off">`;if(type==='channels'){f+=`<label for="url">URL de la fuente</label><input id="url" name="url" type="url" required value="${esc(r.url||'')}" placeholder="https://tu-servidor/canal/index.m3u8"><p class="help">HTTP o HTTPS, sin credenciales en la URL. Usa fuentes propias o autorizadas.</p><label for="group">Categoría</label><input id="group" name="group" required maxlength="80" value="${esc(r.group||'General')}">`;}if(type==='packages'){f+=`<label for="channels">Canales incluidos</label><select id="channels" name="channels" multiple>${db.channels.map(c=>`<option value="${esc(c.id)}" ${(r.channels||[]).includes(c.id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select><p class="help">Ctrl/Cmd + clic para seleccionar varios. Puedes guardar un paquete vacío.</p>`;}if(type==='clients'){f+=`<label for="packageId">Paquete</label><select id="packageId" name="packageId" required>${db.packages.map(p=>`<option value="${esc(p.id)}" ${p.id===r.packageId?'selected':''}>${esc(p.name)}</option>`).join('')}</select><label for="expires">Último día de vigencia</label><input id="expires" name="expires" type="date" required value="${esc(r.expires||new Date(Date.now()+30*864e5).toISOString().slice(0,10))}"><label for="connections">Conexiones permitidas (configuración)</label><input id="connections" name="connections" type="number" min="1" max="100" required value="${r.connections||1}"><p class="help">Pendiente de aplicación en el servidor de streaming.</p>`;}if(type!=='packages')f+=`<label for="enabled">Estado</label><select id="enabled" name="enabled"><option value="true">Habilitado</option><option value="false" ${r.enabled===false?'selected':''}>Suspendido</option></select>`;$('#fields').innerHTML=f;$('#form-error').textContent='';$('#form').onsubmit=async e=>{e.preventDefault();if(sharedCatalog&&formRevision!==catalogClient.revision){$('#form-error').textContent='El catálogo cambió. Cierra este formulario y vuelve a abrir el registro.';return;}const data=new FormData(e.target);const row={id:rid||id(),name:data.get('name').trim()};if(!row.name){$('#form-error').textContent='Escribe un nombre.';return;}if(type==='channels'){if(!validURL(data.get('url'))){$('#form-error').textContent='Usa una URL HTTP o HTTPS sin credenciales.';return;}Object.assign(row,{url:data.get('url'),group:data.get('group').trim()||'General',enabled:data.get('enabled')==='true'});}if(type==='packages')row.channels=data.getAll('channels');if(type==='clients')Object.assign(row,{packageId:data.get('packageId'),expires:data.get('expires'),connections:Number(data.get('connections')),enabled:data.get('enabled')==='true'});const next=structuredClone(db);if(rid)next[type]=next[type].map(x=>x.id===rid?row:x);else next[type].push(row);if(await persist(next)){$('#editor').close();render();toast('Cambios guardados');}else if(sharedCatalog){$('#form-error').textContent=(catalogError||'No se pudo guardar.')+' Cierra este formulario y pulsa Actualizar antes de editar otra vez.';}};$('#editor').showModal();}
async function remove(type,rid){if(!catalogReady||catalogSaving){toast('Actualiza el catálogo antes de eliminar.');return;}const r=db[type].find(x=>x.id===rid);if(type==='packages'&&db.clients.some(c=>c.packageId===rid)){toast('Reasigna los clientes antes de eliminar este paquete.');return;}if(!confirm(`¿Eliminar «${r.name}»?${type==='channels'?' También se quitará de sus paquetes.':''}`))return;const next=structuredClone(db);next[type]=next[type].filter(x=>x.id!==rid);if(type==='channels')next.packages.forEach(p=>p.channels=p.channels.filter(c=>c!==rid));if(await persist(next)){render();toast('Registro eliminado');}}
function m3u(rid){if(!catalogReady){toast('Actualiza el catálogo antes de exportar.');return;}const c=db.clients.find(x=>x.id===rid);if(!c||!active(c)){toast('El cliente debe estar habilitado y vigente.');return;}const p=db.packages.find(p=>p.id===c.packageId);const channels=db.channels.filter(ch=>ch.enabled&&p?.channels.includes(ch.id));if(!channels.length){toast('El paquete no tiene canales habilitados.');return;}const clean=s=>String(s).replace(/[\r\n"\x00-\x1F]/g,' ').trim();download('lista-'+c.name.replace(/[^a-z0-9_-]/gi,'_')+'.m3u','#EXTM3U\n'+channels.map(ch=>`#EXTINF:-1 tvg-name="${clean(ch.name)}" group-title="${clean(ch.group)}",${clean(ch.name)}\n${ch.url}`).join('\n')+'\n','audio/x-mpegurl');toast('Lista exportada con URLs directas, sin control de acceso.');}
async function restore(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>5e6)throw Error('El archivo supera los 5 MB');const next=validate(JSON.parse(await file.text()));if(!confirm(sharedCatalog?'Esto reemplazará todo el catálogo del servidor. ¿Restaurar respaldo?':'Esto reemplazará todos los datos de este navegador. ¿Restaurar respaldo?'))return;if(await persist(next)){render();toast('Respaldo restaurado');}}catch(e){toast('No se pudo restaurar: '+e.message);}};input.click();}
$('#view').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.new)edit(b.dataset.new);if(b.dataset.edit)edit(b.dataset.edit,b.dataset.id);if(b.dataset.delete)remove(b.dataset.delete,b.dataset.id);if(b.dataset.m3u)m3u(b.dataset.m3u);if('backup'in b.dataset)exportBackup();if('import'in b.dataset)restore();});$('#close').onclick=$('#cancel').onclick=()=>$('#editor').close();window.onhashchange=()=>{search='';render();};render();if(!storageOK)toast('No se pudieron leer los datos guardados. No se sobrescribieron; intenta restaurar un respaldo.');

document.addEventListener('click',event=>{if(event.target.closest('[data-catalog-refresh]'))refreshCatalog();if(event.target.closest('[data-catalog-local]'))importLocalCatalog();});
if(sharedCatalog)refreshCatalog();
